    "Manually add expenses and income, assign custom categories, select payment methods, and filter records.": "खर्चों और आय को मैन्युअल रूप से जोड़ें, कस्टम श्रेणियां निर्दिष्ट करें, भुगतान विधियों का चयन करें और रिकॉर्ड फ़िल्टर करें।",
    "Keep tabs on loans you borrow or lend out. Track interest rates, upcoming EMIs, and pending outstanding debts.": "आपके द्वारा उधार लिए गए या उधार दिए गए ऋणों पर नज़र रखें। ब्याज दरों, आगामी ईएमआई और लंबित बकाया ऋणों पर नज़र रखें।",
    "Set custom spending categories and monthly limits. Stay within your boundaries to save more.": "कस्टम व्यय श्रेणियाँ और मासिक सीमाएँ निर्धारित करें। अधिक बचत करने के लिए अपनी सीमाओं के भीतर रहें।",
    "Set aside money for specific savings pools and track milestones toward goals like buying a house or car.": "विशिष्ट बचत पूल के लिए पैसा अलग रखें और घर या कार खरीदने जैसे लक्ष्यों की दिशा में मील के पत्थर ट्रैक करें।",
    "Manage active subscriptions (Netflix, Spotify), set repeating expenses, and receive payment alerts.": "सक्रिय सदस्यताएँ प्रबंधित करें (नेटफ्लिक्स, स्पॉटिफ़ाइ), दोहराए जाने वाले खर्च निर्धारित करें, और भुगतान अलर्ट प्राप्त करें।",
    "Link your Telegram account to chat with our AI Bot. Log entries on-the-go with natural text (e.g.": "हमारे AI बॉट के साथ चैट करने के लिए अपने टेलीग्राम खाते को लिंक करें। प्राकृतिक पाठ के साथ चलते-फिरते प्रविष्टियाँ लॉग करें (उदा.",
    "Toggle Dark Mode, access audit logs for security, and export full reports (PDF or Excel).": "डार्क मोड टॉगल करें, सुरक्षा के लिए ऑडिट लॉग तक पहुंचें और पूरी रिपोर्ट (पीडीएफ या एक्सेल) निर्यात करें।",
    "Read the detailed FAQ to resolve common questions and get step-by-step guides.": "सामान्य प्रश्नों को हल करने और चरण-दर-चरण मार्गदर्शिकाएँ प्राप्त करने के लिए विस्तृत FAQ पढ़ें।",
    "Send feature requests, bug reports, and feedback directly to our development team.": "सुविधा अनुरोध, बग रिपोर्ट और फीडबैक सीधे हमारी विकास टीम को भेजें।",
    "Install ExpenseTracker directly onto your desktop or mobile device home screen for quick offline access.": "त्वरित ऑफ़लाइन पहुंच के लिए सीधे अपने डेस्कटॉप या मोबाइल डिवाइस होम स्क्रीन पर एक्सपेंसट्रैकर इंस्टॉल करें।",
    "No active loans being tracked. Use the calculator on the left and click": "कोई सक्रिय ऋण ट्रैक नहीं किया जा रहा है. बाईं ओर कैलकुलेटर का उपयोग करें और क्लिक करें",
    "M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z": "M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z",
    "Europe/London', 'Europe/Paris', 'Asia/Tokyo', 'Australia/Sydney": "यूरोप/लंदन', 'यूरोप/पेरिस', 'एशिया/टोक्यो', 'ऑस्ट्रेलिया/सिडनी'",
    "Message the bot /start to receive your secure numeric Chat ID.": "अपनी सुरक्षित संख्यात्मक चैट आईडी प्राप्त करने के लिए बॉट/स्टार्ट को संदेश भेजें।",
    "No! Any text typed after the payment mode (or amount) is automatically saved as your entry note.": "नहीं! भुगतान मोड (या राशि) के बाद टाइप किया गया कोई भी टेक्स्ट स्वचालित रूप से आपके प्रवेश नोट के रूप में सहेजा जाता है।",
    "Yes, full decimal precision is supported across all commands! For example,": "हाँ, पूर्ण दशमलव परिशुद्धता सभी आदेशों में समर्थित है! उदाहरण के लिए,",
    "Type /start in your Telegram bot chat anytime to get your Chat ID and reconnect link.": "अपनी चैट आईडी प्राप्त करने और लिंक पुनः कनेक्ट करने के लिए किसी भी समय अपने टेलीग्राम बॉट चैट में टाइप /स्टार्ट करें।",
    "Yes! All user sessions use encrypted JWT authentication, password hashes, and user-isolated database records.": "हाँ! सभी उपयोगकर्ता सत्र एन्क्रिप्टेड JWT प्रमाणीकरण, पासवर्ड हैश और उपयोगकर्ता-पृथक डेटाबेस रिकॉर्ड का उपयोग करते हैं।",
