    "Get support, report technical issues, or request new features directly from our administrators.": "எங்கள் நிர்வாகிகளிடமிருந்து நேரடியாக ஆதரவைப் பெறவும், தொழில்நுட்பச் சிக்கல்களைப் புகாரளிக்கவும் அல்லது புதிய அம்சங்களைக் கோரவும்.",
    "Found an error or issue? Let us know so we can fix it.": "பிழை அல்லது சிக்கலைக் கண்டறிந்தீர்களா? எங்களுக்குத் தெரியப்படுத்துங்கள், நாங்கள் அதை சரிசெய்ய முடியும்.",
    "Want a new dashboard view or tracking tool? Share your thoughts.": "புதிய டாஷ்போர்டு காட்சி அல்லது கண்காணிப்பு கருவி வேண்டுமா? உங்கள் எண்ணங்களைப் பகிர்ந்து கொள்ளுங்கள்.",
    "Get help with authentication changes or importing issues.": "அங்கீகார மாற்றங்கள் அல்லது இறக்குமதி சிக்கல்களுக்கு உதவி பெறவும்.",
    "Ask questions about subscriptions, interest calculations, or layout metrics.": "சந்தாக்கள், வட்டி கணக்கீடுகள் அல்லது தளவமைப்பு அளவீடுகள் பற்றிய கேள்விகளைக் கேளுங்கள்.",
    "Get help retrieving backup data, CSV templates, or deleting your history.": "காப்புப் பிரதி தரவு, CSV டெம்ப்ளேட்கள் அல்லது உங்கள் வரலாற்றை நீக்குதல் போன்றவற்றைப் பெறுவதற்கான உதவியைப் பெறுங்கள்.",
    "Report vulnerabilities, request account deletions, or configure key parameters.": "பாதிப்புகளைப் புகாரளிக்கவும், கணக்கு நீக்கங்களைக் கோரவும் அல்லது முக்கிய அளவுருக்களை உள்ளமைக்கவும்.",
