    "Message the bot /start to receive your secure numeric Chat ID.": "మీ సురక్షిత సంఖ్యా చాట్ IDని స్వీకరించడానికి బోట్/ప్రారంభానికి సందేశం పంపండి.",
    "No! Any text typed after the payment mode (or amount) is automatically saved as your entry note.": "లేదు! చెల్లింపు మోడ్ (లేదా మొత్తం) తర్వాత టైప్ చేసిన ఏదైనా వచనం మీ ఎంట్రీ నోట్‌గా స్వయంచాలకంగా సేవ్ చేయబడుతుంది.",
    "Yes, full decimal precision is supported across all commands! For example,": "అవును, అన్ని ఆదేశాలలో పూర్తి దశాంశ ఖచ్చితత్వానికి మద్దతు ఉంది! ఉదాహరణకు,",
    "Type /start in your Telegram bot chat anytime to get your Chat ID and reconnect link.": "మీ చాట్ IDని పొందడానికి మరియు లింక్‌ని మళ్లీ కనెక్ట్ చేయడానికి ఎప్పుడైనా మీ టెలిగ్రామ్ బాట్ చాట్‌లో టైప్ చేయండి/ప్రారంభించండి.",
    "Yes! All user sessions use encrypted JWT authentication, password hashes, and user-isolated database records.": "అవును! అన్ని వినియోగదారు సెషన్‌లు ఎన్‌క్రిప్టెడ్ JWT ప్రమాణీకరణ, పాస్‌వర్డ్ హాష్‌లు మరియు వినియోగదారు-వివిక్త డేటాబేస్ రికార్డులను ఉపయోగిస్తాయి.",
